create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role text not null check(role in ('student','teacher','counselor','admin')),created_at timestamptz not null default now());
create table if not exists public.subjects(id bigint generated by default as identity primary key,name text not null,created_at timestamptz not null default now());
create table if not exists public.schedules(id bigint generated by default as identity primary key,subject_id bigint not null references public.subjects(id) on delete cascade,weekday smallint not null check(weekday between 1 and 7),start_time time not null,end_time time not null,teacher_id uuid references public.profiles(id),attendance_pin_hash text,created_at timestamptz not null default now());
create table if not exists public.attendance(id bigint generated by default as identity primary key,student_id uuid not null references public.profiles(id) on delete cascade,schedule_id bigint not null references public.schedules(id) on delete cascade,class_date date not null,status text not null check(status in ('present','late','absent','excused')),confirmed_at timestamptz,unique(student_id,schedule_id,class_date));
create table if not exists public.grades(id bigint generated by default as identity primary key,student_id uuid not null references public.profiles(id) on delete cascade,subject_id bigint not null references public.subjects(id) on delete cascade,value numeric(4,2) not null check(value between 0 and 5),label text,created_at timestamptz not null default now());
create table if not exists public.alerts(id bigint generated by default as identity primary key,student_id uuid not null references public.profiles(id) on delete cascade,level text not null check(level in ('follow_up','attention')),reason text not null,recommended_action text,status text not null default 'open' check(status in ('open','reviewed','closed')),created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.subjects enable row level security;alter table public.schedules enable row level security;alter table public.attendance enable row level security;alter table public.grades enable row level security;alter table public.alerts enable row level security;
-- Las politicas RLS se añadiran en una migracion posterior segun el modelo de roles.